using System;

class Program
{
    #nullable disable
    public static void Main()
    {
        Action<int> selfIncr = null;
        selfIncr = value => {
            if (value < 10) 
            {
                Console.WriteLine(value);
                selfIncr(value + 1);
            }
        };
        selfIncr(0);
    }
}
```

