#include <cstdio>
#include <functional>

int main() {
    std::function<void(int)> self_incr = nullptr;
    self_incr = [&self_incr](int value) {
        if (value < 10) {
            printf("%d\n", value);
            self_incr(value + 1);
        }
    };
    self_incr(0);
}
```

### JavaScript (just run them in your browser's F12 console)
```javascript
function main() {
    let selfIncr = null;
    selfIncr = function(value) {
        if (value < 10) {
            console.log(value);
            selfIncr(value + 1);
        }
    };
    selfIncr(0);
}

main();
```

